<?php
declare(strict_types=1);
require_once __DIR__ . '/accounts_common.php';
$user=qbook_require_user();qbook_require_role($user,['ADMIN']);production_require_method('POST');$input=production_input();
accounts_endpoint(function() use($user,$input): array {$type=strtoupper(trim((string)($input['source_type']??'')));$id=(int)($input['source_record_id']??0);if(!in_array($type,['PETTY_CASH_EXPENSE','GENERAL_EXPENSE'],true)||$id<=0)accounts_fail('EXPENSE_SOURCE_NOT_SUPPORTED');$reason=production_clean_text($input['reason']??'',500,'CORRECTION_REASON_REQUIRED');$supplierId=(int)($input['supplier_id']??0);$db=production_db();return accounts_transaction($db,function() use($db,$user,$input,$type,$id,$reason,$supplierId): array {$general=$type==='GENERAL_EXPENSE';$table=$general?'qbook_general_expenses':'qbook_petty_cash_expenses';$supplierColumn=$general?'supplier_name_snapshot':'supplier_paid_to';$s=$db->prepare("SELECT * FROM {$table} WHERE id=? FOR UPDATE");$s->execute([$id]);$expense=$s->fetch();if(!$expense)accounts_fail('EXPENSE_NOT_FOUND',404);if($expense['status']!=='APPROVED'||$expense['journal_id']===null)accounts_fail('EXPENSE_NOT_CORRECTABLE',409);$supplier=accounts_supplier($db,$supplierId);$description=production_clean_text($input['description']??$expense['description'],500,'DESCRIPTION_REQUIRED');$before=['supplier_id'=>$expense['supplier_id'],'supplier_name'=>$expense[$supplierColumn],'description'=>$expense['description']];$after=['supplier_id'=>$supplierId,'supplier_name'=>$supplier['canonical_name'],'description'=>$description];if($before==$after)accounts_fail('NO_CORRECTION_CHANGE');$db->prepare("UPDATE {$table} SET supplier_id=?,{$supplierColumn}=?,description=? WHERE id=? AND status='APPROVED'")->execute([$supplierId,$supplier['canonical_name'],$description,$id]);accounts_audit($db,$user,'EXPENSE_HEADER_CORRECTED',$type,$id,['reason'=>$reason,'locked'=>['amount'=>$expense['amount'],'expense_date'=>$expense['expense_date'],'payment_source'=>$general?$expense['bank_account_id']:$expense['custodian_user_id'],'reference_unchanged'=>true,'evidence_unchanged'=>true],'before'=>$before,'after'=>$after,'journal_impact'=>'0.00']);return ['expense'=>['id'=>$id,'source_type'=>$type,'status'=>'APPROVED'],'journal_impact'=>'0.00'];});});
